class Solution:
    def canConvertString(self, s: str, t: str, k: int) -> bool:
        if len(s) != len(t):
            return False
        need = [0] * 26
        for a, b in zip(s, t):
            need[(ord(b) - ord(a)) % 26] += 1
        for d in range(1, 26):
            if need[d] and d + 26 * (need[d] - 1) > k:
                return False
        return True

