class Solution {
public:
    bool canConvertString(string s, string t, int k) {
        if (s.size() != t.size()) return false;
        long long need[26] = {0};
        for (size_t i = 0; i < s.size(); ++i)
            need[(t[i] - s[i] + 26) % 26]++;
        for (int d = 1; d < 26; ++d)
            if (need[d] > 0 && d + 26 * (need[d] - 1) > (long long)k) return false;
        return true;
    }
};

